import test from 'node:test';import assert from 'node:assert/strict';import {parseItemQuery,itemLink,websiteEnquiry} from '../../listing.mjs';import {fixture} from './fixture.mjs';
test('existing item.html links preserve kind, UUID and exact island',()=>{const item=fixture().items[2],link=itemLink(item,'https://brownnoodyai-sketch.github.io/?private=hidden#old');assert.equal(new URL(link).pathname,'/item.html');assert.equal(new URL(link).hash,'');assert.deepEqual(parseItemQuery(new URL(link).search),{kind:'SERVICE',id:item.id,islandCode:'KADMAT'});assert.ok(!link.includes('private'));});
test('missing, invalid or duplicate island identity cannot open an ambiguous listing',()=>{const item=fixture().items[0],base='?kind=SERVICE&id='+item.id;for(const tail of ['', '&island=__proto__','&island=AGATTI&island=KADMAT'])assert.equal(parseItemQuery(base+tail),null);assert.equal(parseItemQuery('?kind=PRODUCT&id=invalid&island=AGATTI'),null);});
test('prepared enquiry includes exact bot tokens and a working query detail link',()=>{const item=fixture().items[1],url=new URL(websiteEnquiry('919446944562','AGATTI',item,'ml','https://brownnoodyai-sketch.github.io/'));const text=url.searchParams.get('text');assert.match(text,/NOODY_SOURCE:WEBSITE/);assert.match(text,/NOODY_ITEM:PRODUCT:/);assert.match(text,/NOODY_ISLAND:AGATTI/);assert.match(text,/വിശദാംശ/);const page=text.split('Page: ')[1];assert.deepEqual(parseItemQuery(new URL(page).search),{kind:'PRODUCT',id:item.id,islandCode:'AGATTI'});});
test('general enquiry before island selection does not invent item or island',()=>{const text=new URL(websiteEnquiry('919446944562',null,null,'en','https://example.com/?token=private')).searchParams.get('text');assert.match(text,/NOODY_SOURCE:WEBSITE/);assert.ok(!text.includes('NOODY_ITEM:'));assert.ok(!text.includes('NOODY_ISLAND:'));assert.ok(!text.includes('token'));});
test('invalid contact or prototype island cannot produce an outbound link',()=>{assert.equal(websiteEnquiry('bad',null),null);assert.equal(websiteEnquiry('919446944562','__proto__'),null);assert.equal(websiteEnquiry('919446944562',null,fixture().items[0]),null);});
